head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 Column 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > setIgnoreChar]<br/>Body Column 정보를 사용하여 특정 Column 의 ignoreChar 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Body Column 의 ID 를 설정하여 해당 Column 의 ignoreChar 속성을 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body Column 은 col1/col2 = inputType text, col3 = inputType textImage, col4 = inputType secret (메서드 동작 조건).\n[절차] columnInfo(Column ID) / ignoreChar 선택 -> setIgnoreChar 실행 -> 해당 Column 의 셀을 더블클릭하여 제한 문자가 섞인 값을 입력 후 포커스 아웃.\n[확인] columnInfo 를 Column 인덱스 대신 Column ID(col1~col4) 로 지정해도 해당 Column 에 ignoreChar 가 적용되어, 편집 입력값에서 지정 문자가 제거된 결과가 리턴창에 출력된다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (영문 대소문자 + 숫자 + 특수문자 혼합 -> 편집 시 ignoreChar 필터 결과가 드러나도록)
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성한다.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "Ab1-c2", "col2": "He12!Z", "col3": "9a8B7c", "col4": "X9-y8Q" },
        { "col1": "Zz9_8x", "col2": "Wo34?Y", "col3": "1q2W3e", "col4": "Q1-w2R" },
        { "col1": "Mn5,6P", "col2": "Te56#X", "col3": "5t6Y7u", "col4": "E3-r4T" },
        { "col1": "Kk7.8L", "col2": "Co78@W", "col3": "8i9O0p", "col4": "T5-y6U" }
    ]);

    // target 생성
    //  Body Column 4개를 메서드 동작 조건(inputType = text / textImage / secret)으로 구성하고
    //  Column ID 를 col1~col4 로 부여하여 columnInfo 에 ID 를 그대로 전달할 수 있도록 한다.
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" ev:onafteredit="scwin.target1_onafteredit" id="" style="width:640px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" inputType="text" id="hcol1" value="col1 (text)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol2" value="col2 (text)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol3" value="col3 (textImage)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (secret)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="160" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="secret" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setIgnoreChar 실행 : columnInfo 를 Column ID(문자열) 그대로 전달하여 해당 Column 의 ignoreChar 속성을 설정
//  _2 : columnInfo 를 Number 로 변환하지 않고 Column ID 문자열을 그대로 전달한다.
//  쌍이 되는 get 메소드가 없으므로, 전달한 ID 에 해당하는 Column 의 cellInfo 에 반영된 ignoreChar 값을 함께 출력한다.
scwin.btn_setIgnoreChar_onclick = function () {
    let columnInfo = par_columnInfo.getValue();
    let ignoreChar = par_ignoreChar.getValue();

    let ret = scwin.target1.setIgnoreChar(columnInfo, ignoreChar);

    // 전달한 Column ID 가 어느 Column 인덱스인지 확인하여 해당 Column 에 반영됐는지 조회
    let colIdx = -1;
    for (let i = 0; i < 4; i++) {
        if (scwin.target1.getColumnID(i) === columnInfo) {
            colIdx = i;
            break;
        }
    }
    let applied = scwin.target1.getCellInfo(colIdx).options.ignoreChar;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setIgnoreChar('" + columnInfo + "', '" + ignoreChar + "')"
        + (ret === false ? " : 동작 조건 미충족 -> 미동작" : " -> Column ID " + columnInfo + " (인덱스 " + colIdx + ") 에 설정된 ignoreChar : '" + applied + "'"));
}



// 셀 편집 종료(포커스 아웃) 시 발생 : ignoreChar 가 적용된 Column 의 편집 입력값(지정 문자가 제거된 결과)을 출력
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let colId = scwin.target1.getColumnID(columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "onafteredit | [" + rowIndex + ", " + colId + "] 편집 입력값(ignoreChar 적용) : '" + value + "'");
}
